css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader .pool { position: absolute; left: 12%; right: 12%; bottom: 5%; height: 15%; border-radius: 50%; background: radial-gradient(ellipse at 50% 40%, var(--accent-2), var(--accent)); }
.loader .jet { position: absolute; left: 43%; bottom: 12%; width: 14%; height: 0; border-radius: 8px 8px 3px 3px; background: linear-gradient(var(--accent-2), var(--accent)); animation: gey-jet calc(var(--loader-speed) * 2.2) cubic-bezier(.3, 0, .4, 1) infinite; }
.loader i { position: absolute; left: 46%; bottom: 40%; width: 9%; height: 9%; border-radius: 50%; background: var(--accent-2); opacity: 0; animation: gey-spray calc(var(--loader-speed) * 2.2) ease-out infinite; }
.loader i:nth-of-type(1) { --dx: -190%; }
.loader i:nth-of-type(2) { --dx: 20%; --dy: -120%; }
.loader i:nth-of-type(3) { --dx: 200%; }
@keyframes gey-jet { 0%, 26% { height: 0; opacity: .35; } 46% { height: 72%; opacity: 1; } 72% { height: 22%; opacity: .8; } 100% { height: 0; opacity: .35; } }
@keyframes gey-spray { 0%, 40% { opacity: 0; transform: translate(0, 0) scale(.4); } 50% { opacity: 1; transform: translate(0, -20%) scale(1); } 100% { opacity: 0; transform: translate(var(--dx, 0%), var(--dy, 40%)) scale(.5); } }
